const oldChoose=chooseServiceEditor;chooseServiceEditor=function(value){edit=value==='new'?null:{kind:'service',obj:db.services.find(s=>String(s.id)===value)};render();setTimeout(()=>document.getElementById('sname')?.focus(),0)};

function productState(p){return ({pending:'بانتظار موافقة الإدارة',approved:'معتمد ومنشور',rejected:'مرفوض: '+(p.reviewReason||'')})[p.publicationStatus]||'معتمد ومنشور'}
function productImage(p){return p?.mediaUrl?'<img class="service-media" src="'+esc(p.mediaUrl)+'" alt="'+esc(p.name)+'">':''}
products=function(){const selected=edit?.kind==='product'?edit.obj:null;return '<h2>منتجات الصالون</h2>'+db.products.map(p=>'<article class="card">'+productImage(p)+'<h3>'+esc(p.name)+'</h3><p>'+esc(p.description||'')+'</p><p class="money">'+fmt(p.price)+'</p><p class="small">'+esc(productState(p))+'</p><div class="actions"><button class="secondary" data-product-edit="'+esc(p.id)+'">تعديل</button><button class="danger" data-product-withdraw="'+esc(p.id)+'">حذف</button></div></article>').join('')+'<details class="service-editor-fold" open><summary>'+(selected?'تعديل منتج: '+esc(selected.name):'إضافة منتج')+'</summary><div class="card"><label for="productEditorChoice">اختيار المنتج</label><select id="productEditorChoice" onchange="chooseCatalogProduct(this.value)"><option value="new">إضافة منتج</option>'+db.products.map(p=>'<option value="'+esc(p.id)+'" '+(selected?.id===p.id?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select><label for="pname">اسم المنتج</label><input id="pname" type="text" maxlength="160" placeholder="اكتبي اسم المنتج الجديد..." value="'+esc(selected?.name||'')+'"><label for="pdesc">الوصف</label><textarea id="pdesc" maxlength="3000" placeholder="اكتبي وصف المنتج...">'+(esc(selected?.description||''))+'</textarea><label for="pprice">السعر بالدينار</label><input id="pprice" type="number" min="0" step="1" placeholder="أدخلي السعر بالدينار" value="'+(selected?.price??'')+'"><label for="productFile">صورة المنتج أو صورة متحركة</label><input id="productFile" type="file" accept="image/jpeg,image/png,image/gif,image/webp" onchange="previewCatalogProduct()"><div id="productUploadPreview">'+(selected?productImage(selected):'')+'</div><div class="actions"><button id="saveProductButton" type="button" onclick="saveProduct()">'+(account?.id?'إرسال إلى الإدارة للموافقة':'حفظ المنتج')+'</button>'+(selected?'<button class="secondary" onclick="chooseCatalogProduct(\'new\')">إلغاء</button>':'')+'</div></div></details>'};
window.advertisements=function(){return '<h2>الإعلانات والمنتجات</h2><section class="card" data-management-ad aria-label="إعلانات إدارة التطبيق">'+ownerAdMarkup()+'</section><h2>إعلانات منتجات الصالون والصور المرفوعة</h2>'+db.products.filter(p=>p.mediaUrl).map(p=>'<article class="card">'+productImage(p)+'<h3>'+esc(p.name)+'</h3><p class="money">'+fmt(p.price)+'</p><p class="small">'+esc(productState(p))+'</p><button class="secondary" onclick="go(\'products\');editProduct(\''+esc(p.id)+'\')">تعديل المنتج</button></article>').join('')+'<h2>وسائط الخدمات المرفوعة</h2>'+db.services.filter(s=>s.mediaUrl).map(s=>'<article class="card">'+serviceMediaMarkup(s)+'<h3>'+esc(s.name)+'</h3><p class="small">'+esc(({pending:'بانتظار موافقة الإدارة',approved:'معتمدة',rejected:'مرفوضة: '+(s.reviewReason||'')})[s.publicationStatus]||'')+'</p></article>').join('')+'<button class="full" onclick="go(\'products\');document.querySelector(\'.service-editor-fold\').open=true">إضافة منتج وصورته</button>'};
function releaseProductPreview(){const preview=document.getElementById('productUploadPreview');if(preview?.dataset.url)URL.revokeObjectURL(preview.dataset.url)}
window.chooseCatalogProduct=value=>{releaseProductPreview();edit=value==='new'?null:{kind:'product',obj:db.products.find(p=>String(p.id)===String(value))};render();setTimeout(()=>document.getElementById('pname')?.focus(),0)};
window.previewCatalogProduct=()=>{const input=document.getElementById('productFile'),file=input.files[0],box=document.getElementById('productUploadPreview');releaseProductPreview();box.replaceChildren();delete box.dataset.url;if(!file)return;if(!['image/jpeg','image/png','image/gif','image/webp'].includes(file.type)||file.size>20*1024*1024){input.value='';toast('اختاري صورة JPG أو PNG أو GIF أو WebP حتى 20 ميغابايت');return}const image=document.createElement('img');box.dataset.url=URL.createObjectURL(file);image.src=box.dataset.url;image.className='service-media';image.alt='معاينة صورة المنتج';box.append(image)};
editProduct=function(id){chooseCatalogProduct(String(id));document.getElementById('pname')?.scrollIntoView({behavior:'smooth'})};
saveProduct=async function(){if(!account)return toast(errors.login_required);if(busy)return;const selected=edit?.kind==='product'?edit.obj:null,name=val('pname'),description=val('pdesc'),price=Number(val('pprice')),stock=selected?.stock??1,file=document.getElementById('productFile')?.files[0];if(!name||!val('pprice')||!Number.isSafeInteger(price)||price<0)return toast('تحققي من اسم المنتج والسعر');if(!file&&!selected?.mediaId&&!selected?.mediaUrl&&account?.id)return toast('أضيفي صورة المنتج أو صورة متحركة');if(file&&(!['image/jpeg','image/png','image/gif','image/webp'].includes(file.type)||file.size>20*1024*1024))return toast('صيغة الصورة أو حجمها غير مناسب');if(!account?.id){const mediaUrl=file?await fileToUrl(file):(selected?.mediaUrl||'https://images.unsplash.com/photo-1522337360788-8b13dee7a37e?w=600&q=80');if(selected){Object.assign(selected,{name,description,price,stock,mediaUrl,publicationStatus:'approved',active:true})}else{db.products.unshift({id:uid(),name,description,price,stock,active:true,publicationStatus:'approved',mediaUrl})}releaseProductPreview();edit=null;save();toast('تم حفظ المنتج');return}busy=true;const button=document.getElementById('saveProductButton');button.disabled=true;try{let mediaId=selected?.mediaId||null;if(file){const media=await api('media',{method:'POST',headers:{'Content-Type':file.type},body:file});mediaId=media.id}await post('products',{id:selected?._cloudProduct?selected.id:undefined,name,description,price,stock,mediaId,active:true});releaseProductPreview();await refresh();toast('أُرسل المنتج إلى الإدارة — بانتظار الموافقة')}catch(e){toast(e.message)}finally{busy=false;if(button.isConnected)button.disabled=false}};
document.addEventListener('click',async event=>{const editButton=event.target.closest('[data-product-edit]'),withdraw=event.target.closest('[data-product-withdraw]');if(editButton){editProduct(editButton.dataset.productEdit);return}if(!withdraw)return;if(!account)return toast(errors.login_required);const product=db.products.find(p=>String(p.id)===String(withdraw.dataset.productWithdraw));if(!product||busy)return;if(!account?.id){db.products=db.products.filter(p=>String(p.id)!==String(product.id));if(edit?.kind==='product'&&String(edit.obj?.id)===String(product.id))edit=null;save();toast('تم حذف المنتج');return}busy=true;try{await post('products',{...product,active:false});await refresh();toast('أُرسل الطلب إلى الإدارة')}catch(e){toast(e.message)}finally{busy=false}});


