more=function(){return moreBeforeGallery().replace('<button class="full secondary" onclick="go(\'advertisements\')">الإعلانات والمنتجات</button>','')};
services=function(){const prodHtml=productEditorSource().replace('<details class="service-editor-fold" >','<details class="service-editor-fold" open>');return prodHtml+servicesEditorSource()+advertisementEditor()};
products=function(){return '<h2>الإعلانات والمنتجات — المعرض</h2><h3>إعلانات إدارة التطبيق</h3><section class="card" data-management-ad>'+ownerAdMarkup()+'</section><h3>صور وإعلانات منتجات الصالون</h3><div class="owner-gallery">'+db.products.filter(p=>p.mediaUrl).map(p=>'<article class="card"><button class="gallery-open" data-gallery-kind="product" data-gallery-id="'+esc(p.id)+'"><img src="'+esc(p.mediaUrl)+'" alt="'+esc(p.name)+'"><strong>'+esc(p.name)+'</strong></button><p class="small">'+esc(productState(p))+'</p><div class="actions"><button class="secondary" data-product-edit="'+esc(p.id)+'">تعديل</button><button class="danger" data-product-withdraw="'+esc(p.id)+'">حذف</button></div></article>').join('')+'</div><h3>وسائط الخدمات والقصات</h3><div class="owner-gallery">'+db.services.filter(s=>s.mediaUrl).map(s=>'<article class="card"><button class="gallery-open" data-gallery-kind="service" data-gallery-id="'+esc(s.id)+'">'+(s.mediaType?.startsWith('video/')?'<span class="gallery-video-icon">▶</span>':'<img src="'+esc(s.mediaUrl)+'" alt="'+esc(s.name)+'">')+'<strong>'+esc(s.name)+'</strong></button><p class="small">'+esc(catName(s.category))+' · '+fmt(s.price)+'</p><div class="actions"><button class="secondary" data-gallery-edit-service="'+esc(s.id)+'">تعديل</button><button class="danger" data-gallery-remove-service="'+esc(s.id)+'">حذف</button></div></article>').join('')+'</div><button class="full secondary" onclick="go(\'services\')">إضافة منتج أو خدمة</button>'};
window.advertisements=products;
