editProduct=function(id){const item=db.products.find(p=>String(p.id)===String(id));if(!item)return;page='services';edit={kind:'product',obj:item};render();document.getElementById('pname')?.scrollIntoView({behavior:'smooth'})};
document.addEventListener('click',event=>{const open=event.target.closest('[data-gallery-kind]'),editServiceButton=event.target.closest('[data-gallery-edit-service]'),removeService=event.target.closest('[data-gallery-remove-service]');if(editServiceButton)return editService(editServiceButton.dataset.galleryEditService);if(removeService){const s=db.services.find(s=>String(s.id)===String(removeService.dataset.galleryRemoveService));if(s)void catalogWithdraw(s);return}if(!open)return;const item=(open.dataset.galleryKind==='product'?db.products:db.services).find(s=>String(s.id)===String(open.dataset.galleryId));if(!item)return;let dialog=document.getElementById('ownerGalleryDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='ownerGalleryDialog';document.body.append(dialog)}dialog.innerHTML='<h2>'+esc(item.name)+'</h2>'+serviceMediaMarkup(item)+'<p>'+esc(item.description||'')+'</p><p class="money">'+fmt(item.price)+'</p><form method="dialog"><button>إغلاق</button></form>';dialog.showModal()});
const galleryStyle=document.createElement('style');galleryStyle.textContent='.owner-gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.owner-gallery .card{margin:8px 0;padding:10px;min-width:0}.gallery-open{display:block;width:100%;padding:0;background:transparent;color:var(--text)}.gallery-open img{display:block;width:100%;height:115px;object-fit:cover;border-radius:12px;margin-bottom:8px}.gallery-open strong{font-size:12px}.owner-gallery .actions{gap:5px}.owner-gallery .actions button{padding:7px;font-size:11px}.gallery-video-icon{display:grid;place-items:center;height:115px;background:var(--soft);color:var(--pink);border-radius:12px;font-size:40px}#ownerGalleryDialog{width:min(440px,90vw);border:1px solid var(--line);border-radius:17px;background:var(--card);color:var(--text);font:14px Tahoma,Arial,sans-serif;padding:18px}#ownerGalleryDialog::backdrop{background:#0008}';document.head.append(galleryStyle);

let ownerStatement=null,ownerStatementId=null,loadingStatement=false,receiptRequestKey=null;
function agreementHTML(a){return '<article class="card"><h3>'+({proposed:'اتفاق بانتظار موافقتك',accepted:'اتفاق معتمد',rejected:'اتفاق غير معتمد'})[a.status]+'</h3>'+[['service','الخدمات'],['product','المنتجات'],['ad','الإعلانات']].map(([k,title])=>'<p>'+title+': '+fmt(a[k+'_fixed'])+' + '+(a[k+'_bps']/100)+'٪</p>').join('')+(a.status==='proposed'?'<div class="actions"><button data-agreement-id="'+esc(a.id)+'" data-agreement-action="accept">موافقة على الاتفاق</button><button class="secondary" data-agreement-id="'+esc(a.id)+'" data-agreement-action="reject">رفض</button></div>':'')+'</article>'}
async function loadOwnerStatement(){if(!account?.id||loadingStatement)return;loadingStatement=true;try{const value=await api('finance/statement');ownerStatement=value;ownerStatementId=account.id;if(page==='accounts')render()}catch(e){toast(e.message)}finally{loadingStatement=false}}
window.accounts=function(){if(!account?.id){const totalServices=db.bookings.filter(b=>b.status==='done'||b.status==='accepted').reduce((s,b)=>s+Number(b.totalPrice||0),0);return '<h2>حسابات الصالون ('+esc(db.salon?.name||'صالوناتي')+')</h2><div class="card"><p>إجمالي الحجوزات المقبولة والمنجزة: <b>'+fmt(totalServices)+'</b></p><p>عدد الخدمات المتاحة: <b>'+db.services.length+' خدمة</b></p><p>عدد المنتجات المعروضة: <b>'+db.products.length+' منتج</b></p></div>'}if(ownerStatementId!==account.id){ownerStatement=null;ownerStatementId=account.id}if(!ownerStatement){void loadOwnerStatement();return '<h2>حسابات الصالون</h2><p>جارٍ تحميل الحسابات…</p>'}const d=ownerStatement;const balance=e=>e.base_amount-d.receipts.filter(r=>r.event_id===e.id).reduce((n,r)=>n+r.amount,0);return '<h2>حسابات الصالون</h2><div class="actions"><button onclick="refreshSalonAccounts()">تحديث</button><button class="secondary" onclick="printSalonStatement()">طباعة كشف الحساب</button></div><div class="card"><p>المقبوض من الزبائن: <b>'+fmt(d.totals.customer)+'</b></p><p>الوارد من تسويات التوصيل: <b>'+fmt(d.totals.courier)+'</b></p><p>مستحقات الإدارة: <b>'+fmt(d.totals.adminDue)+'</b></p><p>المسدّد للإدارة: <b>'+fmt(d.totals.adminPaid)+'</b></p><p>المتبقي للإدارة: <b>'+fmt(d.totals.adminBalance)+'</b></p></div><section class="card"><h3>اعتماد مخصصات الإدارة</h3><p class="small">يلزم اعتماد اتفاق مستحقات الإدارة قبل الموافقة على الحجوزات.</p>'+(d.agreements?.length?d.agreements.map(agreementHTML).join(''):'<p>لم ترسل الإدارة اتفاق المستحقات بعد. يجب أن تنشئ الإدارة الاتفاق وترسله للموافقة.</p>')+'</section><h2>مصروفات الإدارة المرتبطة بالصالون</h2><p class="small">للعرض فقط وهي على حساب الإدارة.</p>'+((d.adminExpenses||[]).map(e=>'<p>'+esc(e.expense_date)+' — '+esc(e.description)+(e.reference?' · '+esc(e.reference):'')+' · '+fmt(e.amount)+'</p>').join('')||'<p>لا توجد مصروفات مرتبطة.</p>')+'<h2>العمليات الموثقة</h2>'+d.events.map(e=>'<article class="card"><h3>'+({service:'خدمة منفذة',product:'منتج مسلّم',ad:'إعلان'})[e.kind]+'</h3><p>مرجع العملية: '+esc(e.source_id)+'</p><p>قيمة العملية: '+fmt(e.base_amount)+'</p><p>مستحق الإدارة: '+fmt(e.admin_due)+'</p><p>المتبقي للتحصيل: '+fmt(balance(e))+'</p><p class="small">'+esc(new Date(e.occurred_at).toLocaleString('ar-IQ'))+'</p></article>').join('')+(d.events.length?'':'<div class="empty">لا توجد عمليات موثقة للحساب حتى الآن.</div>')+'<details class="service-editor-fold"><summary>تسجيل قبض فعلي أو تسوية توصيل</summary><form class="card" onsubmit="event.preventDefault();recordSalonReceipt()"><label>العملية</label><select id="receiptEvent" required><option value="">اختاري العملية</option>'+d.events.filter(e=>e.kind!=='ad'&&balance(e)>0).map(e=>'<option value="'+esc(e.id)+'">'+esc(e.source_id)+' — المتبقي '+fmt(balance(e))+'</option>').join('')+'</select><label>مصدر المبلغ</label><select id="receiptChannel"><option value="customer">قبض من الزبونة</option><option value="courier">تسوية من وسيط التوصيل</option></select><label>المبلغ المقبوض فعلًا بالدينار</label><input id="receiptAmount" type="number" min="1" step="1" required><label>مرجع سند القبض أو التحويل</label><input id="receiptReference" maxlength="300" required><button type="submit">تسجيل القبض</button></form></details>'};
window.refreshSalonAccounts=()=>void loadOwnerStatement();
window.recordSalonReceipt=async()=>{if(busy)return;const amount=Number(val('receiptAmount')),eventId=val('receiptEvent'),channel=val('receiptChannel'),reference=val('receiptReference');if(!Number.isSafeInteger(amount)||amount<=0||!eventId||!reference)return toast('تحققي من العملية والمبلغ ومرجع القبض');busy=true;receiptRequestKey=receiptRequestKey||crypto.randomUUID();try{await post('finance/receipts',{amount,eventId,channel,reference,requestKey:receiptRequestKey});receiptRequestKey=null;await loadOwnerStatement();toast('تم تسجيل القبض الفعلي')}catch(e){toast(e.message)}finally{busy=false}};
window.printSalonStatement=()=>{if(!ownerStatement||!account)return;const d=ownerStatement,w=window.open('','_blank');if(!w)return toast('اسمحي بفتح نافذة الطباعة');w.opener=null;w.document.write('<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>كشف حساب الصالون</title><style>body{font:14px Tahoma;line-height:1.8;padding:25px}table{width:100%;border-collapse:collapse}td,th{padding:8px;border:1px solid #aaa}h1{font-size:22px}</style><h1>كشف حساب '+esc(account.salonName)+'</h1><p>'+esc(new Date().toLocaleString('ar-IQ'))+'</p><p>قبض الزبائن: '+fmt(d.totals.customer)+' · تسويات التوصيل: '+fmt(d.totals.courier)+'</p><p>مستحقات الإدارة: '+fmt(d.totals.adminDue)+' · المسدّد: '+fmt(d.totals.adminPaid)+' · المتبقي: '+fmt(d.totals.adminBalance)+'</p><table><thead><tr><th>التاريخ</th><th>مرجع العملية</th><th>القيمة</th><th>مستحق الإدارة</th></tr></thead><tbody>'+d.events.map(e=>'<tr><td>'+esc(e.occurred_at)+'</td><td>'+esc(e.source_id)+'</td><td>'+fmt(e.base_amount)+'</td><td>'+fmt(e.admin_due)+'</td></tr>').join('')+'</tbody></table><h2>سندات القبض</h2><table><tr><th>التاريخ</th><th>المصدر</th><th>المبلغ</th><th>المرجع</th></tr>'+d.receipts.map(r=>'<tr><td>'+esc(r.recorded_at)+'</td><td>'+(r.channel==='customer'?'الزبونة':'وسيط التوصيل')+'</td><td>'+fmt(r.amount)+'</td><td>'+esc(r.reference)+'</td></tr>').join('')+'</table><h2>المبالغ المسددة للإدارة</h2><table><tr><th>التاريخ</th><th>المرجع</th><th>المبلغ</th></tr>'+(d.adminPayments||[]).map(p=>'<tr><td>'+esc(p.recorded_at)+'</td><td>'+esc(p.reference)+'</td><td>'+fmt(p.amount)+'</td></tr>').join('')+'</table><h2>مصروفات الإدارة المرتبطة للبيان</h2><table><tr><th>التاريخ</th><th>الوصف</th><th>المبلغ</th></tr>'+(d.adminExpenses||[]).map(e=>'<tr><td>'+esc(e.expense_date)+'</td><td>'+esc(e.description)+(e.reference?' · '+esc(e.reference):'')+'</td><td>'+fmt(e.amount)+'</td></tr>').join('')+'</table><button onclick="window.print()">طباعة</button></html>');w.document.close();w.focus()};
document.addEventListener('click',async event=>{const button=event.target.closest('[data-agreement-id]');if(!button||busy)return;busy=true;try{await post('finance/agreements/'+button.dataset.agreementId,{action:button.dataset.agreementAction});await loadOwnerStatement();toast('تم حفظ قرار الاتفاق')}catch(e){toast(e.message)}finally{busy=false}});
const moreBeforeAccounts=more;more=function(){return '<button class="full secondary" onclick="go(\'accounts\')">حسابات الصالون</button>'+moreBeforeAccounts()};

let salonAds=Array.isArray(db.ads)?db.ads:[],editingSalonAd=null;
const placementNames={salon:'صفحة الصالون فقط',home:'الواجهة الرئيسية',hair:'قسم الشعر',makeup:'قسم المكياج',skin:'قسم العناية بالبشرة',nails:'قسم الأظافر',products:'صفحة المنتجات',discounts:'قسم الخصومات'};
function advertisementEditor(){const a=editingSalonAd;return '<details class="service-editor-fold" '+(a?'open':'')+'><summary>رفع صورة أو إعلان</summary><div class="card"><label>اختيار إعلان</label><select onchange="selectSalonAd(this.value)"><option value="new">جديد</option>'+salonAds.map(v=>'<option value="'+esc(v.id)+'" '+(a?.id===v.id?'selected':'')+'>'+esc(v.title)+'</option>').join('')+'</select><label>عنوان الصورة أو الإعلان</label><input id="salonAdTitle" maxlength="160" value="'+esc(a?.title||'')+'"><label>مكان ظهور الإعلان</label><select id="salonAdPlacement">'+Object.entries(placementNames).map(([key,name])=>'<option value="'+key+'" '+((a?.placement||'salon')===key?'selected':'')+'>'+name+'</option>').join('')+'</select><p class="small">يظهر تلقائيًا في صفحة صالونك والمعرض.</p><label>قيمة الإعلان المتفق عليها بالدينار</label><input id="salonAdBudget" type="number" min="0" step="1" value="'+(a?.budget??0)+'"><label>صورة أو صورة متحركة أو فيديو</label><input id="salonAdFile" type="file" accept="image/jpeg,image/png,image/gif,image/webp,video/mp4,video/webm">'+(a?serviceMediaMarkup({...a,name:a.title}):'')+'<button id="saveSalonAdButton" onclick="submitSalonAd()">'+(account?.id?'حفظ وإرسال مكان الظهور للإدارة':'حفظ الإعلان')+'</button></div></details>'}
window.selectSalonAd=id=>{editingSalonAd=id==='new'?null:salonAds.find(a=>String(a.id)===String(id));render()};
window.submitSalonAd=async()=>{if(!account)return toast(errors.login_required);if(busy)return;const title=val('salonAdTitle'),placement=val('salonAdPlacement'),budget=Number(val('salonAdBudget')),file=document.getElementById('salonAdFile').files[0];if(!Number.isSafeInteger(budget)||budget<0||!title||(!file&&!editingSalonAd?.mediaId&&!editingSalonAd?.mediaUrl&&account?.id))return toast('أضيفي عنوان الإعلان والوسائط');if(file&&!allowedServiceFile(file))return toast('تحققي من نوع الملف وحجمه');if(!account?.id){const mediaUrl=file?await fileToUrl(file):(editingSalonAd?.mediaUrl||'https://images.unsplash.com/photo-1560066984-138dadb4c035?w=600&q=80');const mediaType=file?file.type:(editingSalonAd?.mediaType||'image/jpeg');if(editingSalonAd){Object.assign(editingSalonAd,{title,placement,budget,mediaUrl,mediaType,active:true,publicationStatus:'approved'})}else{salonAds.unshift({id:'ad-'+uid(),title,placement,budget,active:true,publicationStatus:'approved',mediaType,mediaUrl})}db.ads=salonAds;editingSalonAd=null;save();toast('تم حفظ الإعلان في المعرض');return}busy=true;try{let mediaId=editingSalonAd?.mediaId;if(file){mediaId=(await api('media',{method:'POST',headers:{'Content-Type':file.type},body:file})).id}await post('advertisements',{id:editingSalonAd?.id,title,placement,budget,mediaId,active:true});editingSalonAd=null;await refresh();toast('ظهر في صفحة الصالون. الظهور العام بانتظار الإدارة.')}catch(e){toast(e.message)}finally{busy=false}};
const beforeAdMore=more;more=function(){let html=beforeAdMore();const t=document.createElement('template');t.innerHTML=html;const form=t.content.querySelector('#catalogArea')?.closest('form');if(form){const group=document.createElement('div');group.innerHTML='<label>موقع الصالون على الخريطة</label><div class="two"><input id="catalogLatitude" type="number" step="any" placeholder="خط العرض"><input id="catalogLongitude" type="number" step="any" placeholder="خط الطول"></div><button type="button" class="secondary" onclick="fetchSalonLocation(true)">جلب الموقع</button><p id="catalogLocationMessage" class="small" role="status"></p>';const actions=form.querySelector('.actions');form.insertBefore(group,actions)}const lat=t.content.querySelector('#lat'),lng=t.content.querySelector('#lng');if(account&&lat&&lng){lat.value=db.salon?.lat??account.latitude??'';lng.value=db.salon?.lng??account.longitude??'';lat.setAttribute('value',lat.value);lng.setAttribute('value',lng.value);const gps=document.createElement('button');gps.type='button';gps.className='secondary';gps.textContent='جلب الموقع';gps.setAttribute('onclick','fetchSalonLocation(false)');lat.closest('.two').after(gps)}return t.innerHTML};
window.fetchSalonLocation=registration=>{if(!navigator.geolocation)return toast('تحديد الموقع غير متاح في هذا المتصفح');toast('جارٍ تحديد الموقع…');navigator.geolocation.getCurrentPosition(position=>{const lat=document.getElementById(registration?'catalogLatitude':'lat'),lng=document.getElementById(registration?'catalogLongitude':'lng');if(!lat||!lng)return;lat.value=position.coords.latitude.toFixed(6);lng.value=position.coords.longitude.toFixed(6);toast('تم جلب الموقع. احفظي البيانات لإضافته للخريطة.')},error=>toast(error.code===1?'اسمحي بالوصول للموقع من إعدادات المتصفح.':'تعذر تحديد الموقع. حاولي مجددًا.'),{enableHighAccuracy:true,timeout:15000,maximumAge:0})};
const originalSaveSalon=saveSalon;saveSalon=async function(){if(!account)return toast(errors.login_required);if(!account?.id){originalSaveSalon();account.salonName=db.salon.name;account.area=db.salon.area;save();toast('تم حفظ بيانات الصالون');return}const latitude=Number(val('lat')),longitude=Number(val('lng'));if(!val('lat')||!val('lng')||!Number.isFinite(latitude)||latitude< -90||latitude>90||!Number.isFinite(longitude)||longitude< -180||longitude>180)return toast('اجلبي الموقع أو أدخلي إحداثيات صحيحة');try{const d=await post('location',{latitude,longitude,salonName:val('name'),area:val('area')});account=d.account;originalSaveSalon();toast('تم حفظ بيانات الصالون وموقعه على الخريطة')}catch(e){toast(e.message)}};
const galleryBeforeAds=products;products=function(){return '<h2>إعلانات وصور الصالون</h2><div class="owner-gallery">'+salonAds.filter(a=>a.active).map(a=>'<article class="card"><button class="gallery-open" data-own-ad-open="'+esc(a.id)+'">'+(a.mediaType?.startsWith('video/')?'<span class="gallery-video-icon">▶</span>':'<img src="'+esc(a.mediaUrl)+'" alt="'+esc(a.title)+'">')+'<strong>'+esc(a.title)+'</strong></button><p class="small">'+esc(placementNames[a.placement]||'')+' · '+esc(({pending:'بانتظار اعتماد الظهور العام',approved:'الظهور العام معتمد',rejected:'الظهور العام مرفوض'})[a.publicationStatus]||'معتمد')+'</p><div class="actions"><button class="secondary" data-own-ad-edit="'+esc(a.id)+'">تعديل</button><button class="danger" data-own-ad-delete="'+esc(a.id)+'">حذف</button></div></article>').join('')+'</div>'+galleryBeforeAds()};window.advertisements=products;
document.addEventListener('click',async e=>{const open=e.target.closest('[data-own-ad-open]'),editButton=e.target.closest('[data-own-ad-edit]'),del=e.target.closest('[data-own-ad-delete]');if(editButton){editingSalonAd=salonAds.find(a=>String(a.id)===String(editButton.dataset.ownAdEdit));go('services');return}if(del){const a=salonAds.find(a=>String(a.id)===String(del.dataset.ownAdDelete));if(!a)return;if(!account?.id){salonAds=salonAds.filter(x=>String(x.id)!==String(a.id));db.ads=salonAds;if(editingSalonAd&&String(editingSalonAd.id)===String(a.id))editingSalonAd=null;save();toast('تم حذف الإعلان');return}try{await post('advertisements',{...a,active:false});await refresh()}catch(error){toast(error.message)}return}if(!open)return;const a=salonAds.find(a=>String(a.id)===String(open.dataset.ownAdOpen));if(!a)return;let dialog=document.getElementById('ownerGalleryDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='ownerGalleryDialog';document.body.append(dialog)}dialog.innerHTML='<h2>'+esc(a.title)+'</h2>'+serviceMediaMarkup({...a,name:a.title})+'<form method="dialog"><button>إغلاق</button></form>';dialog.showModal()});


const beforeDeliveryAccounts=window.accounts;window.accounts=function(){let html=beforeDeliveryAccounts();if(!account?.id)return html;const t=document.createElement('template');t.innerHTML=scannerPanel();t.content.querySelector('h3').textContent='ماسح باركود تسليم المنتج';t.content.querySelector('.muted').textContent='مسح رمز الزبونة لتأكيد التسليم — للحساب المفوض من الإدارة';return html+t.innerHTML};
const beforeDeliveryScan=submitReceptionScan;submitReceptionScan=async function(value){if(page!=='accounts')return beforeDeliveryScan(value);if(!/^SLP1\.[a-zA-Z0-9-]{1,128}\.[a-f0-9]{64}$/.test(value))return scannerMessage('هذا ليس رمز تسليم منتج صالحًا.');scannerMessage('جارٍ التحقق من التسليم…');try{const d=await post('finance/delivery-scan',{token:value});if(d.status!=='delivered')throw Error('لم يُؤكَّد التسليم');await loadOwnerStatement();scannerMessage('تم تأكيد التسليم. القبض وتسوية التوصيل يسجلان بشكل منفصل.');toast(d.accountingPending?'تم التسليم. تحديث المستحقات بانتظار المزامنة.':'تم تأكيد التسليم وتحديث مستحق الإدارة')}catch(e){scannerMessage(e.message)}};



function registrationFields(data={},signup=false){return '<label>اسم المسؤولة عن الصالون</label><input id="registrationContact" maxlength="120" value="'+esc(data.contactName||'')+'"><label>رقم الهاتف</label><input id="registrationPhone" type="tel" dir="ltr" maxlength="25" value="'+esc(data.phone||'')+'"><label>العنوان التفصيلي</label><textarea id="registrationAddress" maxlength="500">'+esc(data.address||'')+'</textarea><label>صورة واجهة الصالون</label><input id="registrationFacade" type="file" accept="image/jpeg,image/png,image/webp,image/gif">'+(data.facadeUrl?'<img src="'+esc(data.facadeUrl)+'" alt="واجهة الصالون" style="width:100%;max-height:180px;object-fit:contain">':'')}
function registrationInput(signup){const file=document.getElementById('registrationFacade')?.files[0],data={salonName:val(signup?'catalogSalonName':'registrationSalonName'),area:val(signup?'catalogArea':'registrationArea'),contactName:val('registrationContact'),phone:val('registrationPhone'),address:val('registrationAddress'),latitude:val(signup?'catalogLatitude':'registrationLatitude')?Number(val(signup?'catalogLatitude':'registrationLatitude')):null,longitude:val(signup?'catalogLongitude':'registrationLongitude')?Number(val(signup?'catalogLongitude':'registrationLongitude')):null,facadeMediaId:registration?.facadeMediaId};if(!data.salonName||!data.area||!data.contactName||!/^\+?[0-9 ()-]{7,25}$/.test(data.phone)||!data.address||!Number.isFinite(data.latitude)||data.latitude< -90||data.latitude>90||!Number.isFinite(data.longitude)||data.longitude< -180||data.longitude>180){toast('أكملي استمارة التسجيل واجلبي موقع الصالون');return null}if(!file&&!data.facadeMediaId){toast('أضيفي صورة واجهة الصالون');return null}if(file&&(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)||file.size>20*1024*1024)){toast('أضيفي صورة صالحة لا تتجاوز 20 ميغابايت');return null}return {data,file}}
async function sendRegistration(submission){const {data,file}=submission;if(file)data.facadeMediaId=(await api('media',{method:'POST',headers:{'Content-Type':file.type},body:file})).id;await post('registration',data);account={...account,salonName:data.salonName,area:data.area,latitude:data.latitude,longitude:data.longitude}}
window.submitSalonRegistration=async()=>{if(busy||!account)return;const submission=registrationInput(false);if(!submission)return;busy=true;try{await sendRegistration(submission);await refresh();toast('أُرسل طلب التسجيل إلى الإدارة للموافقة')}catch(e){toast(e.message)}finally{busy=false}};
window.registrationGPS=()=>{if(!navigator.geolocation)return toast('تحديد الموقع غير متاح');navigator.geolocation.getCurrentPosition(p=>{document.getElementById('registrationLatitude').value=p.coords.latitude.toFixed(6);document.getElementById('registrationLongitude').value=p.coords.longitude.toFixed(6);toast('تم جلب موقع الصالون')},()=>toast('تعذر جلب الموقع. اسمحي بالوصول للموقع أو أدخلي الإحداثيات.'),{enableHighAccuracy:true,timeout:15000,maximumAge:0})};

const beforeRegistrationMore=more;more=function(){let html=beforeRegistrationMore();if(window.SALONATI_TRIAL)return html;if(!account){const t=document.createElement('template');t.innerHTML=html;const form=t.content.querySelector('#catalogArea')?.closest('form');if(form){const fields=document.createElement('div');fields.innerHTML='<h3>استمارة تسجيل الصالون</h3>'+registrationFields({},true);form.insertBefore(fields,form.querySelector('.actions'))}return t.innerHTML}const status=registration?.status;let card='<section class="card"><h2>طلب تسجيل الصالون</h2><p>'+(({pending:'بانتظار موافقة الإدارة',approved:'تمت الموافقة — الصالون ظاهر للزبونة وعلى الخريطة',rejected:'أُعيد الطلب للتعديل'})[status]||'أكملي الاستمارة لإرسال طلب التسجيل')+'</p>'+(registration?.reason?'<p>'+esc(registration.reason)+'</p>':'');if(status!=='approved')card+='<details '+(status==='pending'?'':'open')+'><summary>استمارة التسجيل</summary><form onsubmit="event.preventDefault();submitSalonRegistration()"><label>اسم الصالون</label><input id="registrationSalonName" maxlength="100" value="'+esc(account.salonName)+'"><label>المنطقة</label><input id="registrationArea" maxlength="100" value="'+esc(account.area)+'">'+registrationFields(registration||{})+'<label>الموقع على الخريطة</label><div class="two"><input id="registrationLatitude" type="number" step="any" placeholder="خط العرض" value="'+esc(registration?.latitude??account.latitude??'')+'"><input id="registrationLongitude" type="number" step="any" placeholder="خط الطول" value="'+esc(registration?.longitude??account.longitude??'')+'"></div><button type="button" onclick="registrationGPS()">جلب الموقع</button><button type="submit">إرسال طلب التسجيل للموافقة</button></form></details>';return card+'</section>'+html};

ownerAdMarkup=function(){const ad=ownerAds[ownerAdIndex%ownerAds.length];if(!ad)return '';return '<small>إعلانات إدارة التطبيق</small><div class="owner-ad-slide">'+(ad.mediaType?.startsWith('video/')?'<video src="'+esc(ad.mediaUrl)+'" autoplay muted loop playsinline style="width:100%;max-height:150px;object-fit:cover;border-radius:10px"></video>':ad.mediaUrl?'<img src="'+esc(ad.mediaUrl)+'" alt="'+esc(ad.title)+'" style="width:100%;height:120px;object-fit:cover;border-radius:10px">':'<span class="ad-product-art" aria-hidden="true">'+esc(ad.symbol||'✿')+'</span>')+'<h2>'+esc(ad.title)+'</h2><p>'+esc(ad.copy)+'</p></div>'};
let managementCampaignSignature='';async function loadManagementCampaigns(){try{const data=await api('public');const signature=JSON.stringify(data.campaigns||[]);if(signature===managementCampaignSignature)return;managementCampaignSignature=signature;ownerAds.splice(0,ownerAds.length,...(data.campaigns||[]));ownerAdIndex=0;paintOwnerAd()}catch{}}
void loadManagementCampaigns();setInterval(()=>{if(!document.hidden)void loadManagementCampaigns()},5000);

const linkedOriginalBooking=booking;booking=function(b){if(!b._linked)return linkedOriginalBooking(b);const original=db.services;db.services=[...b._snapshot.map((x,i)=>({id:'snapshot-'+b.serverId+'-'+i,name:x.name,price:x.price})),...original];try{const t=document.createElement('template');t.innerHTML=linkedOriginalBooking(b);const host=t.content.firstElementChild;if(host)host.insertAdjacentHTML('beforeend',(window.salonatiLoyalty?.html(b.loyalty,b.reward)||'')+(b.rating?'<p>تقييم الزبونة: '+b.rating+' / 5</p>':''));return t.innerHTML}finally{db.services=original}};
const origChangeBooking=changeBooking;changeBooking=async function(uiId,next){if(!account?.id)return origChangeBooking(uiId,next);if(busy)return;const b=db.bookings.find(x=>x.id===uiId&&x._linked);if(!b)return;busy=true;try{await post('workflow/owner/bookings/'+b.serverId,{action:next==='accepted'?'confirm':next==='rejected'?'reject':'complete'});await refresh();toast('تم تحديث الحجز في التطبيقات')}catch(e){toast(e.message)}finally{busy=false}};
async function saveLinkedTeam(body){const r=await fetch('/api/link/team',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok)throw Error('تعذر حفظ بيانات فريق العمل');await refresh()}
const origAddStaff=addStaff,origDeleteStaff=deleteStaff;
addStaff=async function(){if(!account?.id)return origAddStaff();if(busy)return;busy=true;try{await saveLinkedTeam({name:val('staffName'),specialty:val('staffRole')});toast('تم حفظ الموظفة')}catch(e){toast(e.message)}finally{busy=false}};
deleteStaff=async function(id){if(!account?.id)return origDeleteStaff(id);const member=db.staff.find(x=>x.id===id);if(!member||busy)return;busy=true;try{await saveLinkedTeam({action:'delete',id:member.serverId})}catch(e){toast(e.message)}finally{busy=false}};
